WITH filtered AS (SELECT *, CEIL(quantity) AS quantity_whole, ROUND(quantity, 2) AS quantity_rounded FROM inventory WHERE store_id IN (1, 3, 4)) SELECT *, LAST_VALUE(quantity_whole, TRUE) OVER (PARTITION BY store_id, product_id ORDER BY quantity_rounded ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_whole, LEAD(quantity_whole, 2) OVER (PARTITION BY product_id ORDER BY quantity ASC, id ASC) AS next_quantity_whole, NTILE(5) OVER (PARTITION BY product_id ORDER BY quantity_whole DESC, id ASC) AS quantity_whole_bucket FROM filtered;
